from langgraph.types import Command, interrupt

def approval_node(state, tools, clock):
    requested_at = state.get("requested_at") or clock()
    decision = interrupt({"draft": state["draft"], "tool_calls": state["tool_calls"], "requested_at": requested_at})
    if decision.get("approved"):
        result = tools.call("create_receipt", {"donation_id": decision["donation_id"], "sent_to": decision["sent_to"]})
        return {"requested_at": requested_at, "approval": result, "tool_calls": state["tool_calls"] + ["create_receipt"], "route": "done"}
    return {"requested_at": requested_at, "approval": {"status": "rejected", "reason": decision.get("reason", "declined")}, "route": "done"}

